![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

The validation function should explicitly handle missing, null, or non-object inputs by returning a specific error code and failing closed immediately, rather than silently returning empty failures or executing subsequent logic on undefined/null properties. This ensures robust defensive programming and prevents potential runtime errors.

```javascript
export function validatePostAttemptReviewPayloadReadModelRehearsal({ receipt } = {}) {
  const errors = [];
  if (!isRecord(receipt)) {
    errors.push('receipt_required');
    const validatorStatus = 'fail';
    const base = {
      schema_version: VALIDATOR_SCHEMA_VERSION,
      generated_at: DEFAULT_GENERATED_AT,
      generated_by: SCRIPT_NAME,
      issue: ISSUE,
      parent_issue: PARENT_ISSUE,
      depends_on_issues: [...DEPENDS_ON_ISSUES],
      validator_status: validatorStatus,
      receipt_path: DEFAULT_PATHS.receiptOut,
      summary: {
        validation_status: validatorStatus,
        total_post_attempt_review_payload_row_count: null,
        missing_post_attempt_review_payload_row_count: null,
        source_image_only_primary_display_count: null,
        fixture_state_count: null,
        check_count: EXPECTED_CHECK_IDS.length,
        check_pass_count: 0,
        check_fail_count: EXPECTED_CHECK_IDS.length,
        side_effect_receipt_all_zero: false,
      },
      checks: EXPECTED_CHECK_IDS.map((id) => ({ id, status: 'fail' })),
      errors,
    };
    return {
      ...base,
      content_hash: {
        algorithm: 'sha256',
        value: sha256Value({
          schema_version: base.schema_version,
          validator_status: base.validator_status,
          summary: base.summary,
          checks: base.checks,
          errors: base.errors,
        }),
      },
    };
  }

  const summary = receipt.rehearsal_summary ?? {};
