```javascript
function fixtureCoverageErrors(receipt) {
  let queries = [];
  const errors = [];
  if (receipt?.frontend_fixture_query_receipt && Object.hasOwn(receipt.frontend_fixture_query_receipt, 'fixture_state_queries')) {
    if (Array.isArray(receipt.frontend_fixture_query_receipt.fixture_state_queries)) {
      queries = receipt.frontend_fixture_query_receipt.fixture_state_queries;
    } else {
      errors.push('fixture_state_queries_not_an_array');
    }
  }
  const byState = new Map(queries.map((query) => [query?.fixture_state, query]));
